from author import *
c=C('处理机调度与性能计算')
S(c,'调度对象与抢占时机',[T('选择范围','只从当前具备运行条件的候选中选择'),T('非抢占','运行者通常执行到完成或主动等待'),T('抢占','允许按规定条件收回处理器')],[P('调度题先画到达时间线，再确定谁已经进入就绪队列。尚未到达或仍在阻塞的进程，不能因为服务时间短就提前选中。非抢占算法一旦选中进程，通常让它运行到本次工作完成，或者因等待事件主动让出。抢占算法则可以在更高优先级到达、时间片到期等规定条件下中断当前执行。题目没有给抢占规则，不能自己随意添加。',[1,2],['先看候选是否已经就绪','到达时间不是首次运行时间']),P('高层调度决定哪些作业进入系统竞争资源；中层调度常与进程挂起、恢复有关；低层调度直接选择接下来运行的执行对象。不同教材的具体术语要结合上下文，但三者处理的层次不同。调度算法题最常用的是低层时间线，同时要检查是否忽略切换开销、有没有输入输出等待，以及到达和时间片结束同时发生时采用什么入队顺序。',[3],['层次题找调度对象与发生频率','并列事件先写清处理顺序'])],['调度层次与抢占'])
S(c,'周转、等待与响应时间',[R('周转时间',r'T_i=C_i-A_i'),R('带权周转',r'W_i=T_i/S_i'),T('其他指标','等待看就绪排队；响应看第一次获得服务')],[P('先认四个量：到达时间A，完成时间C，服务时间S，周转时间T。周转就是完成减到达，带权周转再除以服务时间。若题目只有一段处理器执行、没有输入输出等待，则等待时间可以用周转减服务。若存在阻塞，这个减法还包含其他等待成分，不能直接都叫就绪等待。每个进程分别算完，最后再求平均。',[1,2],['完成减到达，得到周转','只在相应简化题设下用周转减服务']),P('响应时间关注第一次得到服务之前等了多久，和整个任务多久完成不同。交互系统往往很在意响应；批量计算还会关注吞吐量与周转。平均带权周转要先分别相除，再把各个比值平均，不能用平均周转除以平均服务时间代替。做题时在表格里给每一列写上含义和单位，比只背一个字母更不容易串公式。',[3],['先逐个算比值，再平均','首次响应与最终完成分开'])],['调度性能指标'])
S(c,'先来先服务',[T('题设','A到达0需5；B到达1需3；C到达2需1'),T('FCFS顺序','A：0—5；B：5—8；C：8—9'),T('周转时间','A为5，B为7，C为7；平均19/3')],[P('先来先服务就按进入就绪队列的先后排队。本题先不计切换开销，也没有输入输出：A在零时刻到达，先运行五个时间单位；B在一时刻到达排队，接着从五运行到八；最后C从八到九。注意C虽然只需要一个单位，也不能在非抢占的先来先服务中提前插到A或B前面。先把甘特图画完整，再填完成时间。',[1,2],['按到达顺序排队','本例不计切换与I/O等待'],phase='fcfs',anchor='A在零时刻到达'),P('现在从完成时间减去到达时间。A是五减零，B是八减一，C是九减二，因此周转分别是五、七、七，平均十九除以三。短任务C在长任务后面等了很久，这是先来先服务可能产生的护航效应。算法容易实现，但不能据此说它总能使平均周转最小，评价要看具体目标与任务分布。',[3],['完成时刻减自己的到达时刻','简单公平不等于所有指标最优'],phase='turnaround',anchor='现在从完成时间减去到达时间')],['FCFS','周转计算'],visual=G('schedule',algorithm='fcfs'))
S(c,'短作业与高响应比优先',[T('SJF非抢占','同一题设：先A，再C，最后B'),T('高响应比','R＝（等待时间＋服务时间）／服务时间'),T('在时刻5比较','B为7/3；C为4，因此优先选择C')],[P('仍用刚才的到达和服务数据。零时刻只有A到达，即使知道C未来很短，也不能提前运行尚未到达的C。A在五时刻完成以后，B和C都已就绪，非抢占短作业优先选择C，随后才是B。于是顺序变成A、C、B。短作业优先可能让长作业长期等待，不能把平均表现较好误读成每个进程都获益。',[1],['只比较当前已到达的候选','短作业优先可能造成长作业饥饿'],phase='sjf',anchor='A在五时刻完成以后'),P('高响应比优先同时考虑等待和服务时间。到五时刻，B已经等四个单位，服务需三，响应比是七除以三；C等三个单位，服务需一，响应比是四，因此先选C。这里的响应比不是响应时间，名字相似，公式却不同。等待越久，比值越可能上升，所以它能缓和只照顾短任务的问题；比较时用同一个当前时刻。',[2,3],['响应比不是首次响应时间','各候选用同一当前时刻计算'],phase='hrrn',anchor='到五时刻')],['SJF','HRRN'],visual=G('schedule',algorithm='sjf'))
S(c,'最短剩余时间与时间片轮转',[T('最短剩余时间','新任务到达时，比较剩余服务时间'),T('轮转题设','A、B、C在0到达，服务5、3、1，时间片2'),T('轮转顺序','A、B、C、A、B、A，完成时刻9、8、5')],[P('抢占式短作业常称最短剩余时间优先，比较的是还剩多少工作，而不是始终拿最初的服务时间比较。仍用A零到达需五、B一到达需三、C二到达需一的题设，B到达时A还剩四，所以B可以抢占；C到达时再比较剩余量。若剩余时间相同，还要按题设的并列规则，不能凭感觉随便换人。',[1],['比较剩余量，不是最初总长度','并列情况必须按题设处理']),P('轮转另设三个任务都在零时刻到达，初始队列A、B、C，时间片为二。A先用二，B再用二，C只需一便完成；随后A用二，B用剩下一，A再用最后一。图中各段首尾相接，最终A在九完成，B在八完成，C在五完成。短于时间片的任务提前结束，不要强行补足一个整时间片。',[2,3],['本页轮转例子到达时间全为0','没用完时间片即可完成'],phase='rr',anchor='A先用二')],['SRTF','RR'],visual=G('schedule',algorithm='rr'))
S(c,'优先级、反馈队列与多处理机',[T('优先级','先确认数值越大还是越小越优先'),T('反馈队列','不同优先级、不同时间片及迁移规则'),T('多处理机','兼顾负载均衡、亲和性与同步成本')],[P('优先级题第一步是读清数值约定。有的题用小数值表示高优先级，有的正好相反；还要看是否允许抢占。长期优先照顾某类任务，可能让其他任务饥饿，可以用逐渐提升等待者优先级的老化方法缓和。多级反馈队列还会根据执行行为在队列之间迁移，必须按给定规则处理，不能只凭名称猜升降。',[1,2],['优先级数值方向由题设决定','饥饿可用老化等方式缓和'],phase='mlfq',anchor='多级反馈队列'),P('多处理机题多了一项选择：任务放在哪个处理器上。负载均衡希望减少某些处理器闲着、另一些过忙的情况；处理器亲和性则倾向让任务继续在原来的处理器上运行，以利用已有缓存等状态。两者可能需要折中。多个执行流同时访问共享数据时，调度能力本身并不代替同步互斥，运行得并行仍然可能算出错误结果。',[3],['负载均衡与亲和性可能需要折中','并行执行仍需保护共享数据'],phase='balance',anchor='任务放在哪个处理器上')],['优先级与反馈队列','多处理机调度'],visual=G('queues'))
S(c,'轮转计算练习',[T('题设','A、B同时到达；A需3，B需2，初始A在前'),T('规则','时间片1，无切换开销，无I/O'),T('问题','分别求A、B完成时间与平均周转时间')],[P('暂停画时间线。A和B同时在零时刻到达，A需要三个时间单位，B需要两个，初始队列A在前，时间片为一。没有切换开销，也没有输入输出等待。请按轮转逐格排出执行顺序，分别写出完成时刻，再计算平均周转时间。不要看到A排在前面，就认为A一定比B更早完成。',[1,2,3],['每用一个时间片就更新剩余时间','到达都为0，周转等于完成时刻'])],['调度练习'],kind='question')
S(c,'轮转计算练习答案',[T('执行顺序','A：0—1；B：1—2；A：2—3；B：3—4；A：4—5'),T('完成时刻','A为5，B为4'),T('平均周转','（5＋4）／2＝4.5')],[P('执行顺序是A、B、A、B、A。B在三到四这一段完成，A还剩一个单位，从四运行到五。因此A完成时间五，B完成时间四。两者都在零到达，周转时间分别就是五和四，平均四点五。若算成A先完成，检查是否把先来先服务的连续执行方式误套进了时间片轮转。',[1,2,3],['先画完时间线，再计算指标','轮转不等于按到达顺序一次做完'])],['调度练习'],kind='answer')
c=C('同步、互斥与信号量')
S(c,'共享变量为什么会算错',[T('初值','共享计数器count＝0'),T('一次增加','读取旧值 → 计算加一 → 写回'),T('竞争结果','两条线程都加一，最终却可能只有1')],[P('先把看起来很短的加一拆开。线程A读取零，准备写回一；还没写回，线程B也读到了零，也准备写回一。源代码只有一句，并不保证处理器把整句当成不可分割的操作；是否原子要看实际指令和语言机制。',[1,2],['一句源代码不保证原子执行','先分解读、改、写三个动作'],phase='read',anchor='线程B也读到了零'),P('随后两者都把一写回，最终结果是一，而不是二。错误来自读、改、写的交错，不是数学加法失效。需要排他访问的那段共享资源代码，叫临界区；被多个执行流共享、一次只允许一个使用的资源，叫临界资源。互斥解决同一时刻谁能进去，同步则更广泛地约束先后条件，例如必须先生产再消费。两个词有关联，但不完全相同。考试看到先后次序要求，不能只加一个互斥锁就以为问题已经解决。',[3],['临界区是代码段，临界资源是对象','互斥约束排他，同步约束条件'],phase='write',anchor='两者都把一写回')],['临界区与竞争'],visual=G('race'))
S(c,'互斥机制与原子操作',[T('基本要求','空闲让进、忙则等待、有限等待等'),T('实现手段','软件算法、原子指令、锁与信号量'),T('等待方式','忙等反复检查；阻塞等待让出处理器')],[P('互斥需要控制临界区入口，不能让两个参与者同时进入。常见原则包括空闲时允许进入、有人占用时其他人等待，并尽量避免请求者无限等待。某些软件算法依赖内存访问的顺序假设，不能把教科书伪代码直接当成任意现代机器上的完整实现。用原子交换、测试并设置等指令实现锁时，关键是检查和修改必须不可分割。',[1,2],['关键在于入口检查与修改不可分割','算法成立条件要与题设一致']),P('等待方式也要区分。忙等是在循环中不断检查条件，仍然消耗处理器时间；阻塞等待则让执行流暂停，由系统在条件满足后唤醒。自旋锁不表示自动让权等待。短临界区、多处理机环境下，自旋可能有适用场景，但不能说任何等待都应该自旋。考试先看等待者是否还在执行检查，再判断是哪种方式。',[3],['自旋属于忙等','阻塞后不再持续占用处理器检查'])],['互斥实现','忙等与阻塞'])
S(c,'P与V操作的含义',[T('P操作','申请一个许可；条件不足时等待'),T('V操作','释放许可，并按规则唤醒等待者'),T('互斥初值','mutex＝1，临界区前P，离开后V')],[P('信号量可以先理解成可用许可的计数。P操作申请一个许可，拿不到时必须按实现规则等待；V操作归还许可，并在有等待者时按规则唤醒。操作本身需要原子性，不能把普通变量随手减一就说实现了信号量。互斥信号量通常初始化为一，因为允许一个参与者进入临界区；计数信号量则可以表示多个同类资源。',[1,2],['P申请，V释放','信号量操作本身必须原子'],phase='permit',anchor='P操作申请一个许可'),P('用互斥信号量保护时，在进入临界区前执行P，离开后执行V。一条路径如果漏掉V，其他请求者就可能一直等。记录型信号量教材常把负值用于记录等待数量，但不是所有接口都采用同样的外部计数表示。做题按给定定义计算；只记住负一就是一个可用资源，是错误的。负值若被使用，表示的是等待，不是可用资源。',[3],['mutex初值1，不是0','计数约定以题目定义为准'],phase='lock',anchor='进入临界区前执行P')],['信号量','PV操作'],visual=G('semaphore'))
S(c,'用信号量建立先后关系',[T('要求','A完成步骤a后，B才能执行步骤b'),T('初始化','同步信号量s＝0'),T('安排','A：a；V(s)　B：P(s)；b')],[P('现在只解决先后关系。要求A完成步骤a以后，B才可以执行步骤b。信号量s初始为零，表示完成通知还没有出现。A先做a，再执行V发出通知；B先执行P等待通知，再做b。如果B先到，它会等待；如果A先完成，许可可以留给后来到达的B。这个模式不要求A和B必须在某个固定时刻同时开始。',[1,2],['同步信号量初值通常体现事件未发生','谁产生事件，谁执行对应V'],phase='before',anchor='A先做a'),P('填空题可以用一句话检验：P放在需要等待的操作之前，V放在产生条件的操作之后。若把B的P放到b后面，已经来不及阻止b提前执行。若信号量初始为一，B可能不等A就直接通过，也破坏了题目要求。多个先后关系常需要分别设置信号量，先画约束箭头，再给每条箭头配通知与等待。',[3],['先画a→b，再放P和V','P要放在受约束步骤之前'],phase='after',anchor='P放在需要等待的操作之前')],['前驱同步关系'],visual=G('precedence'))
S(c,'生产者与消费者的计数',[T('缓冲区容量N','empty＝N；full＝0；mutex＝1'),T('生产者','P(empty) → P(mutex) → 放入'),T('消费者','P(full) → P(mutex) → 取出')],[P('把缓冲区看成一排有限的格子。生产者放东西之前，要确认还有空格，因此先申请empty；消费者取东西之前，要确认已有产品，因此先申请full。初始缓冲区为空，所以empty等于容量N，full为零。mutex只负责保护修改缓冲区的临界区，初值一；它不能代替空格和产品这两个不同条件。三个信号量的职责不要混在一起。假设容量三，一开始三个空位、零个产品。',[1,2,3],['empty数空位，full数产品','mutex只保护临界访问'],phase='empty',anchor='生产者放东西之前'),P('生产者成功放入一个以后，应当归还互斥锁，并通知full增加一个可消费许可；消费者取走一个以后，则通知empty增加一个空位。稳定状态下，空位加产品数量等于容量，但执行过程中的许可可能暂时被参与者持有，所以不要在任意指令之间机械套用表面计数相加等于N。',[1,2,3],['完成放入后通知full','完成取出后通知empty'],phase='produce',anchor='生产者成功放入一个以后')],['生产者消费者初始化'],visual=G('buffer',capacity=3))
S(c,'生产消费的完整PV顺序',[T('生产者','P(empty)；P(mutex)；放入；V(mutex)；V(full)'),T('消费者','P(full)；P(mutex)；取出；V(mutex)；V(empty)'),T('检查重点','先等资源条件，再占互斥锁')],[P('把两条路径完整读一遍。生产者先等空位，再加互斥锁，放入以后释放互斥锁，最后发出产品通知。消费者先等产品，再加锁，取出以后解锁，最后发出空位通知。两边都需要锁，但等待的资源条件不同；把消费者的P写成empty，会使它等待错误的对象。写完后分别模拟空缓冲区和满缓冲区，是最有效的检查方法。',[1,2],['两边等的计数条件不同','空与满两个边界都要模拟']),P('为什么通常先等资源，再拿互斥锁？看空缓冲区：若消费者先拿mutex，再因full为零而等待，它会抱着锁不放；生产者想放入产品，也需要这把锁，于是双方可能互相卡住。错误不在于使用了信号量，而在于把等待资源和占用互斥锁的顺序写反。按照题目的原子操作定义，逐行推演谁持有什么，就能找到问题。',[3],['不要持有缓冲区锁等待产品或空位','逐行跟踪持有者和等待者'])],['生产者消费者PV顺序'])
S(c,'读者写者与哲学家问题',[T('读者写者','多个读者可共享；写者通常要求独占'),T('公平性','读者优先可能使写者长期等待'),T('资源顺序','按统一顺序申请，可破坏循环等待')],[P('读者写者问题与普通互斥不同：多个读者只读取时可以同时访问，但写者修改数据时通常需要独占。读者优先方案允许后来读者继续加入，可能让写者长期等不到机会。题目若要求公平或写者优先，就不能照抄读者优先的代码。先判断允许哪些参与者同时进入，再考虑计数变量、保护读者数量的锁和控制写入的资源锁。',[1,2],['读读可共享，读写通常互斥','优先策略影响是否可能饥饿']),P('哲学家就餐可以抽象为每个参与者需要两件资源。如果所有人先拿左边，再等待右边，就可能形成一圈等待。给资源统一编号，要求所有人按同一编号顺序申请，是一种破坏循环等待的思路。它说明解题关键在资源依赖，不在故事名称。是否还满足公平、并发度如何，需要继续结合具体方案分析，不能只说不会死锁就包办所有要求。',[3],['先画资源依赖关系','避免死锁不等于自动保证公平'])],['读者写者','哲学家就餐'])
S(c,'同步顺序练习',[T('题设','缓冲区为空，full＝0，mutex＝1'),T('错误消费者','P(mutex)；P(full)；取出；……'),T('问题','为什么可能卡住？前两步应怎样调整？')],[P('暂停推演。缓冲区为空，消费者先执行P互斥锁，再执行P产品信号量。生产者也要拿同一把互斥锁才能放入产品。消费者为什么可能卡住？请具体指出消费者手里拿着什么、正在等什么，生产者又在等什么。最后写出消费者入口处两个P操作的正确先后顺序。',[1,2,3],['不要只回答顺序写反','说明双方的持有与等待'])],['同步互斥练习'],kind='question')
S(c,'同步顺序练习答案',[T('卡住的原因','消费者拿着mutex等full，生产者又等mutex'),T('正确入口','P(full)；P(mutex)；取出'),T('正确出口','V(mutex)；V(empty)')],[P('消费者先占住mutex，然后因为没有产品而阻塞；生产者要放入产品，却拿不到mutex，双方可能无法继续。正确入口应先P产品，再P互斥锁，取出后先释放互斥锁，再通知空位增加。这里先等产品条件，保证消费者不会抱着缓冲区锁等待产品。这道题也是下一章分析资源依赖和死锁的具体入口。',[1,2,3],['先等资源条件，再进入临界区','释放锁与通知对应计数要完整'])],['同步互斥练习'],kind='answer')

